// Safe Merge: دمج بيانات العميل الجديدة (من AI) مع البيانات القديمة (من الشيت)
// القاعدة: أي قيمة جديدة فاضية/placeholder -> نحتفظ بالقديمة. غير كده -> نستخدم الجديدة.

const newData = $('Code in JavaScript1').item.json.customer || {};

const oldRows = $('فحص العميل1').all().filter(r => Object.keys(r.json).length > 0);
const oldData = oldRows.length > 0 ? oldRows[0].json : {};

function isEmpty(v) {
  if (v === undefined || v === null) return true;
  const s = String(v).trim();
  return s === '' || s === '-' || s === 'null' || s === 'undefined';
}

// خريطة: اسم الحقل عند الـ AI => اسم العمود المقابل في شيت العملاء (للقيم القديمة)
const fieldMap = {
  name:              'اسم العميل',
  governorate:       'المحافظة',
  area:              'المنطقة',
  notes:             'الملاحظات',
  requested_product: 'المنتج المطلوب',
  customer_type:     'الحالة'
};

const merged = {};

for (const [aiField, sheetColumn] of Object.entries(fieldMap)) {
  const newVal = newData[aiField];
  const oldVal = oldData[sheetColumn];

  if (!isEmpty(newVal)) {
    // AI استخرج قيمة حقيقية (سواء بيانة جديدة أو تعديل صريح من العميل) -> خدها
    merged[aiField] = newVal;
  } else if (!isEmpty(oldVal)) {
    // الجديد فاضي/placeholder -> احتفظ بالقديم
    merged[aiField] = oldVal;
  } else {
    // مفيش قديم ولا جديد
    merged[aiField] = '-';
  }
}

return [{ json: merged }];

const trigger = $('استقبال رسالة واتساب1').item.json;
const msg = trigger.messages ? trigger.messages[0] : null;

// تجاهل الأحداث اللي مش رسائل (تحديثات حالة: تم الإرسال/التسليم/القراءة)
if (!msg) {
  return [];
}

const phone = msg.from;
const tail = String(phone).replace(/\D/g, '').slice(-10);

// فحص المحظورين: هل رقم المرسِل موجود في أي خانة في شيت المحظورين؟
const blockedRows = $('فحص المحظورين1').all();
const blocked = blockedRows.some(r =>
  Object.values(r.json).some(v => {
    const d = String(v).replace(/\D/g, '');
    return d.length >= 10 && d.slice(-10) === tail;
  })
);

const customerRows = $('فحص العميل1').all().filter(r => Object.keys(r.json).length > 0);
const existing = customerRows.length > 0 ? customerRows[0].json : null;
const status = existing ? existing.Status : null;

// أنواع الرسائل اللي مش نصية ولا زرار (ريكورد/صوت/صورة/فيديو/ملف/ملصق)
const mediaTypes = ['audio', 'voice', 'image', 'video', 'document', 'sticker'];
const isMedia = mediaTypes.includes(msg.type);

let route;
if (blocked || status === 'closed_no_transfer' || status === 'closed_transfer') {
  route = 'stop';
} else if (isMedia) {
  route = 'media';
} else if (!existing && msg.type === 'text') {
  route = 'welcome';
} else {
  route = 'agent';
}

let agent_input;
if (msg.type === 'interactive') {
  const id = msg.interactive.button_reply.id;
  if (id === 'inquiry') agent_input = 'العميل دوس على زرار: عندي استفسار. ابدأ تجمع بياناته.';
  else if (id === 'transfer_yes') agent_input = 'العميل دوس على زرار: تحويل لخدمة العملاء. حوله دلوقتي.';
  else if (id === 'transfer_no') agent_input = 'العميل دوس على زرار: لا شكرًا. سجل بياناته واقفل من غير تحويل.';
  else agent_input = id;
} else {
  agent_input = msg.text?.body || '';
}

return [{ json: { phone, route, agent_input } }];

const raw = $json.output || '';
let parsed;
try {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  let jsonPart = raw.substring(start, end + 1);
  jsonPart = jsonPart.replace(/[\x00-\x1F]+/g, ' ');
  parsed = JSON.parse(jsonPart);
} catch (e) {
  parsed = {
    reply_text: 'معلش، ممكن توضحلي طلبك تاني؟',
    actions: ['reply'],
    customer_profile_complete: false,
    customer: { name:'-', customer_type:'-', governorate:'-', area:'-', requested_product:'-', notes:'-' },
    missing_fields: [],
    discount_percentage: '-'
  };
}
return [{ json: parsed }];

