// تجميع رسائل العميل المتتالية قبل استدعاء الـ AI
const staticData = $getWorkflowStaticData('global');
const phone = $json.phone;
const now = Date.now();

if (!staticData.pending) staticData.pending = {};
if (!staticData.pending[phone]) staticData.pending[phone] = { messages: [], lastTs: 0 };

staticData.pending[phone].messages.push($json.agent_input);
staticData.pending[phone].lastTs = now;

return [{ json: { ...$json, myTs: now } }];

// لو وصلت رسالة أحدث من نفس العميل أثناء الانتظار، أوقف هذا التنفيذ
// وسيب آخر تنفيذ (الأحدث) هو اللي يجمع كل الرسائل ويكمل
const staticData = $getWorkflowStaticData('global');
const phone = $json.phone;
const myTs = $json.myTs;
const entry = staticData.pending ? staticData.pending[phone] : null;

if (!entry || entry.lastTs !== myTs) {
  return [];
}

const combined = entry.messages.join('\n');
delete staticData.pending[phone];

return [{ json: { ...$json, agent_input: combined } }];
